                    return steps.map((st, i) => (
                      <div key={i} className={`ai-trace-item ${st.tone ?? ''}`}>
                        <span className="ai-trace-icon">{st.icon}</span>
                        <span className="ai-trace-text">{st.text}</span>
                      </div>
