                  const runs = q ? agentRuns.filter((r) => r.task.toLowerCase().includes(q)) : agentRuns
                  if (runs.length === 0) return <div className="ai-welcome-page dim" style={{ padding: '20px', textAlign: 'center' }}>검색 결과가 없습니다.</div>
                  return (
