                    onAccept={() => acceptPtask(t.id)}
                    onRerun={() => rerunPtask(t)}
                    onConfirm={(approved) => respondPtaskConfirm(t.id, approved)}
                    onAnswerChange={(v) => setPtaskAnswer(t.id, v)}
