                            <button className="ai-history-icon" onClick={(e) => beginTaskRename(s, e)} title="이름 변경">✎</button>
                            <button className="ai-saved-del" onClick={(e) => deleteSavedTask(s.id, e)} title="삭제">×</button>
                          </>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
