                        onDragOver={(e) => { e.preventDefault(); setDragOverFolder(f.id) }}
                        onDragLeave={() => setDragOverFolder((prev) => (prev === f.id ? null : prev))}
                        onDrop={(e) => onFolderDrop(f.id, e)}
