                  <div className="ai-welcome-page" title={pageInfo.url}>📄 {pageInfo.title || hostOf(pageInfo.url)}</div>
                ) : (
                  <div className="ai-welcome-page dim">웹 페이지에서 열면 그 페이지 내용을 함께 봅니다.</div>
