                    <div className="ai-msg-role">{m.role === 'user' ? '나' : 'AI'}</div>
                    <div className="ai-msg-text">
                      {m.role === 'assistant' && !m.error && m.content
                        ? <Markdown text={m.content} windowId={windowId} />
