                      {AGENT_EXAMPLES.map((ex) => (
                        <button key={ex.label} className="ai-example-btn" onClick={() => fillAgentTask(ex.task)} title={ex.task}>{ex.label}</button>
                      ))}
                    </div>
                  </div>
                )}
