                    <span className="ai-trace-icon">{t.icon}</span>
                    <span className="ai-trace-text">
                      {t.text}
                      {t.shot && <img className="ai-trace-shot" src={`data:image/png;base64,${t.shot}`} alt="완료 화면" />}
