.ai-target-sub { font-size: 10px; color: var(--color-text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ai-task-trace { display: flex; flex-direction: column; gap: 3px; margin-top: 6px; max-height: 110px; overflow-y: auto; }

