import { startTaskRuntimeServer } from './task-runtime-server.mjs'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const REPO = path.resolve(__dirname, '..')

  await sleep(5000)
  const pub3 = (await srv.counts()).publish
