const grant = W.grantAutoPublish({ platform: 'instagram', accounts: ['me'], maxPosts: 2, minutes: 30 })
t('정상 입력이면 선승인이 만들어진다', !!grant && grant.maxPosts === 2, JSON.stringify(grant))
