let genWorkspaceId = 'ws-1'
// 생성 작업의 체크포인트가 기억하는 **대상 탭의 복원 안정 키**. 게시 준비는 옛 탭 id 가 아니라
// 이 키로 대상을 되찾는다 — 재시작 뒤 같은 id 가 다른 탭을 가리키기 때문이다.
