      //   (구간 시작의 원장 관문이 결국 잡기는 했지만, 그전까지 상태가 "재시도 중" 으로 표시돼
      //    사용자에게 **진행 중인 것처럼** 보였고 backoff 도 헛되이 태웠다.)
      const uncertain = pendingExternalWrite(live)
